#define CK(x) do{if((x)!=cudaSuccess)throw std::runtime_error(#x);}while(0)
const int G=8,R=3;const float GUARD=1048575.f,POISON=-12345.5f;
template<class T>std::vector<T>readv(const char*n){std::ifstream f(n,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("openfixture");size_t z=f.tellg();if(z%sizeof(T))throw std::runtime_error("dtype");f.seekg(0);std::vector<T>v(z/sizeof(T));if(!f.read((char*)v.data(),z))throw std::runtime_error("shortfixture");return v;}
struct State{Case c;std::vector<float>host[7];float*dev[7];State(Case q,std::vector<float>&f):c(q){int size=q.n*q.m;for(int k=0;k<7;k++){host[k].assign(size+16,GUARD);for(int j=0;j<size;j++)host[k][j+G]=k<4?f.at(q.io+k*size+j):POISON;CK(cudaMalloc(&dev[k],host[k].size()*4));}}void reset(){for(int k=0;k<7;k++)CK(cudaMemcpy(dev[k],host[k].data(),host[k].size()*4,cudaMemcpyHostToDevice));CK(cudaDeviceSynchronize());}float*p(int k){return dev[k]+G;}std::vector<float>get(int k){auto v=host[k];CK(cudaMemcpy(v.data(),dev[k],v.size()*4,cudaMemcpyDeviceToHost));return v;}};
void capture(State&s,std::vector<double>&o){for(int k=0;k<7;k++)for(auto x:s.get(k))o.push_back(x);}
template<class F>double phase(F op){op();CK(cudaGetLastError());CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int r=0;r<R;r++)op();CK(cudaGetLastError());CK(cudaDeviceSynchronize());return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/R;}
double run(State&s,std::vector<double>&stages){int n=s.c.n,m=s.c.m,mode=s.c.mode,it=0;for(int q=n/2;q>1;q>>=1)it++;int ptrs[]={0,1,2,3,4},tmp=5;bool re=mode==5||mode==7||mode==8;auto tr=[&](int src,int dst,int w,int h){return phase([&]{transpose<<<dim3(w/16,h/16),dim3(16,16)>>>(s.p(dst),s.p(src),w,h);});};if(re)for(int k=0;k<4;k++){stages.push_back(tr(ptrs[k],tmp,n,m));std::swap(ptrs[k],tmp);}auto a=s.p(ptrs[0]),b=s.p(ptrs[1]),c=s.p(ptrs[2]),d=s.p(ptrs[3]),x=s.p(ptrs[4]),w=s.p(6);stages.push_back(phase([&]{switch(mode){case 0:pcr_small_systems_kernel<<<m,n,5*(n+1)*4>>>(a,b,c,d,x,n,m,it);break;case 1:pcr_branch_free_kernel<<<m,n,5*(n+1)*4>>>(a,b,c,d,x,n,m,it);break;case 2:cyclic_small_systems_kernel<<<m,n/2,5*(n+1)*4>>>(a,b,c,d,x,n,m,it);break;case 3:cyclic_branch_free_kernel<<<m,n/2,5*(n+1)*4>>>(a,b,c,d,x,n,m,it);break;case 4:case 5:sweep_small_systems_global_kernel<<<((m+255)/256),256>>>(a,b,c,d,x,w,n,m,re);break;case 6:case 7:sweep_small_systems_local_kernel<<<((m+255)/256),256>>>(a,b,c,d,x,n,m,re);break;case 8:sweep_small_systems_global_vec4_kernel<<<((m+255)/256)*4,64>>>(a,b,c,d,x,w,n,m,re);break;}}));if(re){stages.push_back(tr(ptrs[4],tmp,m,n));std::swap(ptrs[4],tmp);}double total=0;for(auto z:stages)total+=z;return total;}
bool check(State&s,std::vector<double>&o,double&maxerr,double&maxback){auto c=s.c;int z=c.n*c.m;bool re=c.mode==5||c.mode==7||c.mode==8,ok=true;for(int k=0;k<7;k++){auto v=s.get(k);bool numeric=(!re&&k==4)||(re&&(k==3||k==4))||(k==6&&(c.mode==4||c.mode==5||c.mode==8));for(int j=0;j<z+16;j++){if(j<8||j>=z+8){ok&=v[j]==GUARD;continue;}double want=o[c.oo+k*z+j-8],err=fabs(v[j]-want);maxerr=std::max(maxerr,err);ok&=std::isfinite(v[j])&&(numeric?err<=2e-5+2e-4*fabs(want):v[j]==want);}}auto x=s.get(re?3:4);for(int sys=0;sys<c.m;sys++){double an=0,xn=0,bn=0,rn=0;for(int i=0;i<c.n;i++){int j=sys*c.n+i+8;double aa=s.host[0][j],bb=s.host[1][j],cc=s.host[2][j],rhs=s.host[3][j],xx=x[j];double residual=bb*xx-rhs;if(i)residual+=aa*x[j-1];if(i+1<c.n)residual+=cc*x[j+1];rn=std::max(rn,fabs(residual));an=std::max(an,fabs(aa)+fabs(bb)+fabs(cc));xn=std::max(xn,fabs(xx));bn=std::max(bn,fabs(rhs));}double back=rn/(an*xn+bn);maxback=std::max(maxback,back);ok&=std::isfinite(back)&&back<=1e-5;}return ok;}
int main(){auto f=readv<float>("input_f32.bin");auto o=readv<double>("oracle_f64.bin");std::vector<State*>states;for(auto c:cases)states.push_back(new State(c,f));for(int trial=1;trial<=5;trial++){std::vector<double>pre,post;bool ok=true;double sec=0,maxerr=0,maxback=0;for(auto*s:states){s->reset();capture(*s,pre);std::vector<double>stages;sec+=run(*s,stages);ok&=check(*s,o,maxerr,maxback);capture(*s,post);printf("STUDY_CASE trial=%d case=%d mode=%d stage_seconds=",trial,s->c.case_id,s->c.mode);for(auto tm:stages)printf("%.12g,",tm);printf("\n");}pre.insert(pre.end(),post.begin(),post.end());std::string path="tridiagonal_trial"+std::to_string(trial)+".bin";std::ofstream(path,std::ios::binary).write((char*)pre.data(),pre.size()*8);printf("STUDY_TRIAL {\"trial\":%d,\"correct\":%s,\"jit_excluded\":true,\"time_seconds\":%.12g,\"internal_repeats\":3,\"timing_region\":\"sum45_original_solver_paths_and_individual_reorder_stages_warm_then_three_call_batch_completion\",\"max_abs_error\":%.12g,\"max_normwise_backward_error\":%.12g,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"shape\":[%zu],\"byte_order\":\"little\"}}\n",trial,ok?"true":"false",sec,maxerr,maxback,path.c_str(),pre.size(),pre.size());fflush(stdout);}}
